#include <stdio.h>
#include <ctype.h>
int main(void) {
    char s[] = "AbC";
    for (int i = 0; s[i]; i++) {
        s[i] = (char)tolower((unsigned char)s[i]);
    }
    printf("%s\n", s);
    return 0;
}

