#include <stdio.h>
#include <string.h>
int main(void) {
    char s[16] = "hello";
    fgets(s, sizeof(s), stdin);
    s[strcspn(s, "\n")] = 0;
    printf("%s %d\n", s, (int)strlen(s));
    return 0;
}

