#include <stdio.h>
#include <string.h>
int main(void) {
    char *a = "apple";
    char *b = "apply";
    int r = strcmp(a, b);
    printf("%d\n", r < 0 ? -1 : (r > 0 ? 1 : 0));
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void) {
    char d[5] = "AB";
    char s[] = "CDEF";
    strncat(d, s, 2);
    printf("%s %d\n", d, (int)strlen(d));
    return 0;
}

#include <stdio.h>
#include <ctype.h>
int main(void) {
    char s[] = "a1B2c";
    int up = 0, low = 0;
    for (int i = 0; s[i]; i++) {
        if (isupper((unsigned char)s[i])) up++;
        else if (islower((unsigned char)s[i])) low++;
    }
    printf("%d %d\n", up, low);
    return 0;
}
